public static class BuffDetailViewCodec
{
    public static BuffDetailView Decode(byte[] payload)
    {
        var reader = new BinaryReader(payload);
        var value = new BuffDetailView();
        while (!reader.EndOfMessage)
        {
            var tag = reader.ReadTag();
            switch (tag.FieldNumber)
            {
                case 1 when tag.WireType == 0:
                    value.UnitId = reader.ReadUInt32();
                    break;
                case 2 when tag.WireType == 0:
                    value.BuffInstanceId = reader.ReadUInt64();
                    break;
                case 3 when tag.WireType == 0:
                    value.AbsorbRemaining = reader.ReadUInt32();
                    break;
                case 4 when tag.WireType == 0:
                    value.Revision = reader.ReadUInt32();
                    break;
                default:
                    reader.Skip(tag.WireType);
                    break;
            }
        }
        return value;
    }

    public static byte[] Encode(BuffDetailView value)
    {
        var writer = new BinaryWriter();
        if (value.UnitId != 0) writer.WriteUInt32(1, value.UnitId);
        if (value.BuffInstanceId != 0) writer.WriteUInt64(2, value.BuffInstanceId);
        if (value.AbsorbRemaining != 0) writer.WriteUInt32(3, value.AbsorbRemaining);
        if (value.Revision != 0) writer.WriteUInt32(4, value.Revision);
        return writer.ToArray();
    }
}

